class Solution:

	def internalSearch(self, idx, target, r, c, mat, max_row, max_col):
		found = 0
		if (r >= 0 and r <= max_row) and (c >= 0 and c <= max_col) and (target[idx] == mat[r][c]):
			match = target[idx]
			idx += 1
			mat[r][c] = 0
			if idx == len(target):
				found = 1
			else:
				found += self.internalSearch(idx, target, r, c + 1, mat, max_row, max_col)
				found += self.internalSearch(idx, target, r, c - 1, mat, max_row, max_col)
				found += self.internalSearch(idx, target, r + 1, c, mat, max_row, max_col)
				found += self.internalSearch(idx, target, r - 1, c, mat, max_row, max_col)
			mat[r][c] = match
		return found

	def findOccurrence(self, mat, target):
		res = 0
		row_count = len(mat)
		col_count = len(mat[0])
		for r in range(row_count):
			for c in range(col_count):
				res += self.internalSearch(0, target, r, c, mat, row_count - 1, col_count - 1)
		return res
